package main

func add(a, b int) int {
	return a + b
}

// reverse reverses s without changing its length.
func reverse[T ~string | ~[]byte | ~[]rune](s T) T {
	switch v := any(s).(type) {
	case string:
		r := []rune(v)
		for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
			r[i], r[j] = r[j], r[i]
		}
		return any(string(r)).(T)
	case []byte:
		b := append([]byte(nil), v...)
		for i, j := 0, len(b)-1; i < j; i, j = i+1, j-1 {
			b[i], b[j] = b[j], b[i]
		}
		return any(b).(T)
	case []rune:
		r := append([]rune(nil), v...)
		for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
			r[i], r[j] = r[j], r[i]
		}
		return any(r).(T)
	}
	return s
}

func Reverse[T ~string | ~[]byte | ~[]rune](s T) T {
	return reverse(s)
}

func reverseString(s string) string {
	return reverse(s)
}

func ReverseString(s string) string {
